package com.smartinternship.service; import com.smartinternship.model.*; import com.smartinternship.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.reactive.function.client.WebClient; import java.util.*; @Service public class AiRecommendationService { private final StudentRepository sr; private final InternshipOfferRepository or; private final WebClient client; public AiRecommendationService(StudentRepository s,InternshipOfferRepository o,@Value("${ai.service.url}") String url){sr=s;or=o;client=WebClient.builder().baseUrl(url).build();} public List<Map<String,Object>> recommend(Long id){Student s=sr.findById(id).orElseThrow(); Map<String,Object> body=new HashMap<>(); body.put("student",Map.of("fullName",s.getFullName(),"skills",Objects.toString(s.getSkills(),""),"preferredDomain",Objects.toString(s.getPreferredDomain(),""),"experienceMonths",Objects.toString(s.getExperienceMonths(),"0"))); body.put("offers",or.findAll().stream().map(o->Map.of("id",o.getId(),"title",o.getTitle(),"company",o.getCompany(),"domain",Objects.toString(o.getDomain(),""),"requiredSkills",Objects.toString(o.getRequiredSkills(),""),"location",Objects.toString(o.getLocation(),""))).toList()); return client.post().uri("/recommend").bodyValue(body).retrieve().bodyToFlux(Map.class).map(x->(Map<String,Object>)x).collectList().block();} }